Fixes: b83d23a2a38b ("openvswitch: Introduce per-cpu upcall dispatch")
Acked-by: Aaron Conole <aconole@redhat.com>
Signed-off-by: Andrey Zhadchenko <andrey.zhadchenko@virtuozzo.com>
Link: https://lore.kernel.org/r/20220825020326.664073-1-andrey.zhadchenko@virtuozzo.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The bug is caused by the failure to free the allocated memory for the `upcall_portids` array when the `new_vport()` function fails during the execution of `ovs_dp_cmd_new()`. This results in a memory leak, as the allocated memory remains unreferenced and is not released back to the system.

Here is the patch:

 static int ovs_dp_cmd_new(struct sk_buff *skb, struct genl_info *info)
 {
 	struct nlattr **a = info->attrs;
 	struct vport_parms parms;
 	struct sk_buff *reply;
 	struct datapath *dp;
 	struct vport *vport;
 	struct ovs_net *ovs_net;
 	int err;

 	err = -EINVAL;
 	if (!a[OVS_DP_ATTR_NAME] || !a[OVS_DP_ATTR_UPCALL_PID])
 		goto err;

 	reply = ovs_dp_cmd_alloc_info();
 	if (!reply)
 		return -ENOMEM;

 	err = -ENOMEM;
 	dp = kzalloc(sizeof(*dp), GFP_KERNEL);
 	if (dp == NULL)
 		goto err_destroy_reply;

 	ovs_dp_set_net(dp, sock_net(skb->sk));

 	/* Allocate table. */
 	err = ovs_flow_tbl_init(&dp->table);
 	if (err)
 		goto err_destroy_dp;

 	err = ovs_dp_stats_init(dp);
 	if (err)
 		goto err_destroy_table;

 	err = ovs_dp_vport_init(dp);
 	if (err)
 		goto err_destroy_stats;

 	err = ovs_meters_init(dp);
 	if (err)
 		goto err_destroy_ports;

 	/* Set up our datapath device. */
 	parms.name = nla_data(a[OVS_DP_ATTR_NAME]);
 	parms.type = OVS_VPORT_TYPE_INTERNAL;
 	parms.options = NULL;
 	parms.dp = dp;
 	parms.port_no = OVSP_LOCAL;
 	parms.upcall_portids = a[OVS_DP_ATTR_UPCALL_PID];

 	/* So far only local changes have been made, now need the lock. */
 	ovs_lock();

 	err = ovs_dp_change(dp, a);
 	if (err)
 		goto err_unlock_and_destroy_meters;

 	vport = new_vport(&parms);
 	if (IS_ERR(vport)) {
 		err = PTR_ERR(vport);
 		if (err == -EBUSY)
 			err = -EEXIST;

 		if (err == -EEXIST) {
 			/* An outdated user space instance that does not understand
 			 * the concept of user_features has attempted to create a new
 			 * datapath and is likely to reuse it. Drop all user features.
 			 */
 			if (info->genlhdr->version < OVS_DP_VER_FEATURES)
 				ovs_dp_reset_user_features(skb, info);
 		}

-		goto err_unlock_and_destroy_meters;
+		goto err_destroy_portids;
 	}

 	err = ovs_dp_cmd_fill_info(dp, reply, info->snd_portid,
 				   info->snd_seq, 0, OVS_DP_CMD_NEW);
 	BUG_ON(err < 0);

 	ovs_net = net_generic(ovs_dp_get_net(dp), ovs_net_id);
 	list_add_tail_rcu(&dp->list_node, &ovs_net->dps);

 	ovs_unlock();

 	ovs_notify(&dp_datapath_genl_family, reply, info);
 	return 0;

+err_destroy_portids:
+	kfree(rcu_dereference_raw(dp->upcall_portids));
 err_unlock_and_destroy_meters:
 	ovs_unlock();
 	ovs_meters_exit(dp);
 err_destroy_ports:
 	kfree(dp->ports);
 err_destroy_stats:
 	free_percpu(dp->stats_percpu);
 err_destroy_table:
 	ovs_flow_tbl_destroy(&dp->table);
 err_destroy_dp:
 	kfree(dp);
 err_destroy_reply:
 	kfree_skb(reply);
 err:
 	return err;
 }



